class OLFenceRegistry {
  constructor(definitions) {
    this.definitions = definitions.slice();
    this.definitionsByHeader = new Map(
      this.definitions.map((definition) => [definition.header, definition]),
    );
    this.headerPrefixDefinitions = this.definitions
      .slice()
      .sort((left, right) => right.header.length - left.header.length);
  }

  getDefinitions() {
    return this.definitions.slice();
  }

  findByHeader(header) {
    return this.definitionsByHeader.get(header) || null;
  }

  parseHeader(info) {
    for (const definition of this.definitions) {
      const parsedHeader = definition.parseHeader(info);
      if (parsedHeader) {
        return parsedHeader;
      }
    }

    return null;
  }

  getFenceBlockKind(info) {
    return this.parseHeader(info)?.kind || 'unknown';
  }

  getRequiredDeclaredPartNames() {
    return this.definitions
      .filter((definition) => definition.required)
      .map((definition) => definition.header);
  }

  getSnippetDefinitions() {
    const seenHeaders = new Set();

    return this.definitions
      .flatMap((definition) => definition.getSnippetDefinitions())
      .filter(({ header }) => {
        if (seenHeaders.has(header)) {
          return false;
        }

        seenHeaders.add(header);
        return true;
      });
  }

  findHeaderPrefix(info) {
    for (const definition of this.headerPrefixDefinitions) {
      if (!info.startsWith(definition.header)) {
        continue;
      }

      const nextCharacter = info[definition.header.length];
      if (!nextCharacter || /\s|\(/.test(nextCharacter)) {
        return definition;
      }
    }

    return null;
  }

  getFenceHeaderError(info) {
    const configDefinition = this.findByHeader('Config');

    if (info === 'config') {
      return 'Use ol:Config. Lowercase ol:config is not supported.';
    }

    if (
      configDefinition &&
      info.startsWith(configDefinition.header) &&
      !configDefinition.parseHeader(info)
    ) {
      return 'Config fences cannot be numbered or suffixed.';
    }

    const sectionDefinition = this.findHeaderPrefix(info);
    if (sectionDefinition) {
      const remainder = info.slice(sectionDefinition.header.length).trimStart();
      const indexMatch = remainder.match(/^(\d+)/);

      if (indexMatch) {
        if (!sectionDefinition.allowsNumbering) {
          return `${sectionDefinition.header} fences cannot be numbered.`;
        }

        if (indexMatch[1].startsWith('0')) {
          return 'Section indexes must start at 1.';
        }
      }
    }

    return 'Unsupported ol part. Use Config, Intro, Instrumental, Interlude, lyric sections, Breakdown, Vamp, or Solo.';
  }
}

export { OLFenceRegistry };
