import { OLFenceDefinition } from './OLFenceDefinition.ts';

class OLOutro extends OLFenceDefinition {
  constructor() {
    super({
      className: 'OLOutro',
      header: 'Outro',
      kind: 'outro',
      description: 'Lyric or progression section fence.',
      tokenState: 'olOutro',
    });
  }

  validateBody(context) {
    context.validators.validateOutroBlock(
      context.bodyLines,
      context.startLineNumber,
      context.markers,
    );
  }

  renderPreviewBody(context) {
    return context.helpers.renderMixedLineCollection(context.lineEntries);
  }
}

export { OLOutro };
