import {
  CONFIG_FIELD_NAMES,
  normalizeConfigFieldName,
} from '../../../../../editor/scripts/shared.ts';
import { describeChordKey } from '../../music-theory.ts';
import { OLFenceDefinition } from './OLFenceDefinition.ts';

function getSingleLineValueEntry(entry) {
  if (!entry || !Array.isArray(entry.values) || entry.values.length !== 1) {
    return null;
  }

  return entry.values[0] || null;
}

function renderEditableKeyField(context, valueEntry) {
  const keyText = String(valueEntry?.text ?? '').trim();
  const keyTitle = keyText ? describeChordKey(keyText) : 'Choose key';
  const chordDataAttributes = keyText
    ? ` data-chord-key="${context.helpers.escapeHtml(keyText)}" data-chord-title="${context.helpers.escapeHtml(keyTitle)}"`
    : '';

  return [
    '<span class="ol-preview-config__field-control">',
    `<button class="ol-preview-chord ol-preview-config__key-trigger${keyText ? '' : ' ol-preview-config__key-trigger--empty'}" type="button" data-preview-action="toggle-config-key-menu" data-config-field="Key" data-config-current-value="${context.helpers.escapeHtml(keyText)}" aria-haspopup="menu" aria-expanded="false" aria-label="${context.helpers.escapeHtml(keyText ? `Change key from ${keyText}` : 'Choose key')}" title="${context.helpers.escapeHtml(keyText ? `Change key from ${keyText}` : 'Choose key')}"${chordDataAttributes}${context.helpers.getEditorDataAttributes(
      valueEntry?.lineEntry?.lineNumber,
      valueEntry?.valueColumn || valueEntry?.lineEntry?.column,
    )}>${context.helpers.escapeHtml(keyText || 'Choose key')}</button>`,
    '</span>',
  ].join('');
}

function renderEditableTimeField(context, valueEntry) {
  const timeText = String(valueEntry?.text ?? '').trim();

  return [
    '<span class="ol-preview-config__field-control">',
    `<button class="ol-preview-config__time-trigger${timeText ? '' : ' ol-preview-config__time-trigger--empty'}" type="button" data-preview-action="toggle-config-time-menu" data-config-field="Time" data-config-current-value="${context.helpers.escapeHtml(timeText)}" aria-haspopup="menu" aria-expanded="false" aria-label="${context.helpers.escapeHtml(timeText ? `Change time signature from ${timeText}` : 'Choose time signature')}" title="${context.helpers.escapeHtml(timeText ? `Change time signature from ${timeText}` : 'Choose time signature')}"${context.helpers.getEditorDataAttributes(
      valueEntry?.lineEntry?.lineNumber,
      valueEntry?.valueColumn || valueEntry?.lineEntry?.column,
    )}>${context.helpers.escapeHtml(timeText || 'Choose time')}</button>`,
    '</span>',
  ].join('');
}

function getTempoInputValue(valueText) {
  const normalizedValue = String(valueText ?? '').trim();

  if (!normalizedValue) {
    return '';
  }

  const tempoMatch = normalizedValue.match(/^(\d+)(?:\s*bpm)?$/i);

  if (tempoMatch) {
    return String(Number.parseInt(tempoMatch[1], 10));
  }

  return normalizedValue.replace(/\s*bpm$/i, '');
}

function renderEditableTempoField(context, valueEntry) {
  const tempoValueText = getTempoInputValue(valueEntry?.text);
  const hasTempoValue = Boolean(tempoValueText);

  return [
    '<span class="ol-preview-config__field-control">',
    `<button class="ol-preview-config__tempo-trigger${hasTempoValue ? '' : ' ol-preview-config__tempo-trigger--empty'}" type="button" data-preview-action="toggle-config-tempo-menu" data-config-field="Tempo" data-config-current-value="${context.helpers.escapeHtml(tempoValueText)}" aria-haspopup="dialog" aria-expanded="false" aria-label="${context.helpers.escapeHtml(hasTempoValue ? `Change tempo from ${tempoValueText} bpm` : 'Choose tempo')}" title="${context.helpers.escapeHtml(hasTempoValue ? `Change tempo from ${tempoValueText} bpm` : 'Choose tempo')}"${context.helpers.getEditorDataAttributes(
      valueEntry?.lineEntry?.lineNumber,
      valueEntry?.valueColumn || valueEntry?.lineEntry?.column,
    )}>${context.helpers.escapeHtml(tempoValueText || 'Choose tempo')}</button>`,
    hasTempoValue
      ? '<span class="ol-preview-config__tempo-suffix" aria-hidden="true">bpm</span>'
      : '',
    '</span>',
  ].join('');
}

function renderAttachmentsAddAction() {
  return [
    '<div class="ol-preview-config__attachments-action">',
    '<button class="ol-preview-config__part-action" type="button" data-preview-action="toggle-config-attachment-menu" aria-haspopup="dialog" aria-expanded="false" aria-label="Add attachment" title="Add attachment">+</button>',
    '</div>',
  ].join('');
}

function renderConfigAttachmentsValue(context, entry) {
  const attachmentItems = entry.values
    .map((value) => {
      const rawValueText = String(value.text ?? '');
      const trimmedValueText = rawValueText.trim();
      const sourceIndex = String(value.sourceIndex ?? '');

      if (!trimmedValueText) {
        return '';
      }

      return `<div class="ol-preview-config__attachment-item" data-attachment-source-index="${context.helpers.escapeHtml(
        sourceIndex,
      )}"${context.helpers.getEditorDataAttributes(
        value.lineEntry.lineNumber,
        value.valueColumn || value.lineEntry.column,
      )}>${context.helpers.renderInlineText(rawValueText)}<button class="ol-preview-config__attachment-remove" type="button" data-preview-action="remove-config-attachment" data-attachment-source-index="${context.helpers.escapeHtml(
        sourceIndex,
      )}" aria-label="Remove attachment ${context.helpers.escapeHtml(trimmedValueText)}" title="Remove attachment"></button></div>`;
    })
    .filter(Boolean);

  if (!attachmentItems.length) {
    return `<div class="ol-preview-config__attachments-value ol-preview-config__attachments-value--empty">${renderAttachmentsAddAction()}</div>`;
  }

  return [
    '<div class="ol-preview-config__attachments-value">',
    `<div class="ol-preview-config__attachments-list">${attachmentItems.join('')}</div>`,
    renderAttachmentsAddAction(),
    '</div>',
  ].join('');
}

function renderMissingConfigAction(context, missingFieldNames) {
  if (!missingFieldNames.length) {
    return '';
  }

  return [
    '<div class="ol-preview-config__missing-actions">',
    `<button class="ol-preview-config__add-button" type="button" data-preview-action="toggle-config-add-menu" data-config-missing-fields="${context.helpers.escapeHtml(
      missingFieldNames.join('||'),
    )}" aria-haspopup="menu" aria-expanded="false" aria-label="Add missing config field" title="Add missing config field">Add Config</button>`,
    '</div>',
  ].join('');
}

function renderEditableConfigValue(context, entry) {
  const valueEntry = getSingleLineValueEntry(entry);

  if (!valueEntry) {
    return null;
  }

  if (entry.key === 'Key') {
    return renderEditableKeyField(context, valueEntry);
  }

  if (entry.key === 'Time') {
    return renderEditableTimeField(context, valueEntry);
  }

  if (entry.key === 'Tempo') {
    return renderEditableTempoField(context, valueEntry);
  }

  return null;
}

class OLConfig extends OLFenceDefinition {
  constructor() {
    super({
      className: 'OLConfig',
      header: 'Config',
      kind: 'config',
      description: 'Song metadata fence.',
      tokenState: 'olConfig',
      required: true,
    });
  }

  getSnippetBodyLines() {
    return [
      '- Title: Your Song Title Here',
      '- Subtitle:',
      '- Description:',
      '- Artist: Song Artist Here',
      '- Copyright: Copyright Your Name Here',
      '- Key: G',
      '- Tempo: 70bpm',
      '- Time: 4/4',
      '- Theme:',
      '- Structure: IV1CV2CO',
      '- Genre:',
      '- Style:',
      '- Attachments:',
      '- Strumming Patterns:',
      '  $0',
    ];
  }

  validateBody(context) {
    context.validators.validateConfigBlock(
      context.bodyLines,
      context.startLineNumber,
      context.markers,
      context.declaredParts,
    );
  }

  renderPreviewBody(context) {
    const entries = [];
    let currentEntry = null;

    for (const lineEntry of context.lineEntries) {
      const line = lineEntry.text;

      if (!line.trim()) {
        continue;
      }

      const fieldMatch = line.match(/^\s*-\s*([^:]+):\s*(.*)$/);
      if (fieldMatch) {
        const label = fieldMatch[1].trim();
        const separatorOffset = line.indexOf(':');
        const valueOffset =
          separatorOffset === -1 ? line.length : separatorOffset + 1;
        const valueIndentLength =
          line.slice(valueOffset).match(/^\s*/)?.[0].length || 0;
        currentEntry = {
          key: normalizeConfigFieldName(label),
          label,
          lineEntry,
          values: [
            {
              text: fieldMatch[2],
              lineEntry,
              valueColumn: valueOffset + valueIndentLength + 1,
              sourceIndex: 0,
            },
          ],
        };
        entries.push(currentEntry);
        continue;
      }

      if (currentEntry) {
        currentEntry.values.push({
          text: line.trim(),
          lineEntry,
          valueColumn: lineEntry.column,
          sourceIndex: currentEntry.values.length,
        });
        continue;
      }

      return context.helpers.renderLineCollection(context.lineEntries);
    }

    const entryMap = new Map(entries.map((entry) => [entry.key, entry]));
    const missingFieldNames = CONFIG_FIELD_NAMES.filter((fieldName) => {
      return !entryMap.has(fieldName);
    });

    if (!entries.length) {
      return [
        '<div class="ol-preview-config-shell">',
        context.helpers.renderEmptyBody(),
        renderMissingConfigAction(context, missingFieldNames),
        '</div>',
      ].join('');
    }
    const keyText = String(
      getSingleLineValueEntry(entryMap.get('Key'))?.text ?? '',
    ).trim();
    const timeSignatureText =
      entryMap
        .get('Time')
        ?.values.map((value) => String(value.text ?? '').trim())
        .filter(Boolean)
        .join(' ') || '4/4';
    const tempoText = getTempoInputValue(
      getSingleLineValueEntry(entryMap.get('Tempo'))?.text,
    );
    const strummingPatternPreviewContext = entryMap.has('Strumming Patterns')
      ? context.helpers.createStrummingPatternPreviewContextFromConfigBody(
          context.body,
          {
            sourceLocation: context.sourceLocation,
          },
        )
      : null;

    return [
      '<div class="ol-preview-config-shell">',
      '<dl class="ol-preview-config">',
      ...entries.flatMap((entry) => {
        const isAttachments = entry.key === 'Attachments';
        const isStrummingPatterns = entry.key === 'Strumming Patterns';
        const isMultiline =
          isStrummingPatterns || isAttachments || entry.values.length > 1;
        const editableValueHtml = renderEditableConfigValue(context, entry);
        const valueHtml =
          editableValueHtml ??
          (isAttachments
            ? renderConfigAttachmentsValue(context, entry)
            : entry.key === 'Structure'
              ? context.helpers.renderStructureValue(entry.values)
              : isStrummingPatterns
                ? context.helpers.renderConfigStrummingPatternValue(
                    entry.values,
                    timeSignatureText,
                    {
                      keyText,
                      patterns: strummingPatternPreviewContext?.patterns,
                      tempoText,
                    },
                  )
                : entry.values
                    .map((value) => {
                      const rawValueText = String(value.text ?? '');
                      const trimmedValueText = rawValueText.trim();
                      const renderedValueText =
                        entry.key === 'Key' && trimmedValueText
                          ? context.helpers.renderInlineText(
                              `[${trimmedValueText}]`,
                            )
                          : context.helpers.renderInlineText(rawValueText);

                      return `<span${context.helpers.getEditorDataAttributes(
                        value.lineEntry.lineNumber,
                        value.valueColumn || value.lineEntry.column,
                      )}>${renderedValueText}</span>`;
                    })
                    .join('<br>'));
        return [
          `<div class="ol-preview-config__entry${isMultiline ? ' ol-preview-config__entry--stacked' : ' ol-preview-config__entry--inline'}">`,
          `<dt class="ol-preview-config__key${isStrummingPatterns ? ' ol-preview-config__key--patterns' : ''}"${context.helpers.getEditorDataAttributes(
            entry.lineEntry.lineNumber,
            entry.lineEntry.column,
          )}>${context.helpers.escapeHtml(entry.label || entry.key)}:</dt>`,
          `<dd class="ol-preview-config__value${isStrummingPatterns ? ' ol-preview-config__value--patterns' : ''}${entry.key === 'Structure' ? ' ol-preview-config__value--structure' : ''}"${context.helpers.getEditorDataAttributes(
            entry.lineEntry.lineNumber,
            entry.lineEntry.column,
          )}>${valueHtml}</dd>`,
          '</div>',
        ];
      }),
      '</dl>',
      renderMissingConfigAction(context, missingFieldNames),
      '</div>',
    ].join('');
  }
}

export { OLConfig };
