import {
  getRegisteredSpellcheckSpecification,
  getRegisteredSpellcheckSpecifications,
} from './editor-plugin-registry.ts';
import TypoConstructor from 'typo-js';

const TYPO_VERSION = '1.3.1';
const ENGLISH_WORD_RE = /[A-Za-z]+(?:['’][A-Za-z]+)*/g;
const ENGLISH_WORD_EXACT_RE = /^[A-Za-z]+(?:['’][A-Za-z]+)*$/;
const BUILT_IN_SPELLCHECK_SPECIFICATIONS = [
  {
    actionLabel: 'English Spell Checker',
    aff: `https://cdn.jsdelivr.net/npm/typo-js@${TYPO_VERSION}/dictionaries/en_US/en_US.aff`,
    aliases: ['en', 'en-us', 'en_us'],
    defaultEnabled: true,
    dictionaryName: 'en_US',
    dict: `https://cdn.jsdelivr.net/npm/typo-js@${TYPO_VERSION}/dictionaries/en_US/en_US.dic`,
    displayName: 'English',
    exactWordPattern: ENGLISH_WORD_EXACT_RE,
    languageCode: 'en',
    normalizeWord(word) {
      return String(word || '')
        .replace(/[’]/g, "'")
        .replace(/^'+|'+$/g, '');
    },
    wordPattern: ENGLISH_WORD_RE,
  },
];

function testRegExp(pattern, value) {
  if (!(pattern instanceof RegExp)) {
    return false;
  }

  pattern.lastIndex = 0;
  return pattern.test(value);
}

function getBuiltInSpellcheckSpecification(languageCode) {
  return (
    BUILT_IN_SPELLCHECK_SPECIFICATIONS.find(
      (specification) => specification.languageCode === languageCode,
    ) || null
  );
}

function getAvailableSpellcheckSpecifications() {
  return BUILT_IN_SPELLCHECK_SPECIFICATIONS.concat(
    getRegisteredSpellcheckSpecifications(),
  );
}

function normalizeLanguageCode(languageCode) {
  const normalizedValue = String(languageCode || '')
    .trim()
    .toLowerCase();

  if (!normalizedValue) {
    return null;
  }

  const matchingSpecification = getAvailableSpellcheckSpecifications().find(
    (specification) => specification.aliases?.includes(normalizedValue),
  );

  return matchingSpecification?.languageCode || null;
}

function getSpellcheckSpecification(languageCode) {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);
  if (!normalizedLanguageCode) {
    return null;
  }

  return (
    getBuiltInSpellcheckSpecification(normalizedLanguageCode) ||
    getRegisteredSpellcheckSpecification(normalizedLanguageCode)
  );
}

function getNormalizedDictionaryUrl(...values) {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) {
      return value.trim();
    }
  }

  return '';
}

function getNormalizedDictionaryUrls(...values) {
  const normalizedUrls = [];

  values.forEach((value) => {
    if (Array.isArray(value)) {
      value.forEach((entry) => {
        if (typeof entry === 'string' && entry.trim()) {
          normalizedUrls.push(entry.trim());
        }
      });
      return;
    }

    if (typeof value === 'string' && value.trim()) {
      normalizedUrls.push(value.trim());
    }
  });

  return Array.from(new Set(normalizedUrls));
}

function getPrimaryDictionaryUrls(dictionarySource) {
  return {
    affUrl: getNormalizedDictionaryUrl(
      dictionarySource.affUrl,
      dictionarySource.aff,
      dictionarySource.af,
    ),
    dicUrl: getNormalizedDictionaryUrl(
      dictionarySource.dicUrl,
      dictionarySource.dic,
      dictionarySource.dict,
    ),
  };
}

function getSuggestionDictionaryUrls(dictionarySource) {
  return {
    affUrls: getNormalizedDictionaryUrls(
      dictionarySource.suggestAffUrls,
      dictionarySource.suggestAffs,
      dictionarySource.suggestAffUrl,
      dictionarySource.suggestAff,
      dictionarySource.suggestAfUrls,
      dictionarySource.suggestAf,
    ),
    dicUrl: getNormalizedDictionaryUrl(
      dictionarySource.suggestDicUrl,
      dictionarySource.suggestDic,
      dictionarySource.suggestDict,
    ),
  };
}

function getDictionarySource(languageCodeOrSpecification) {
  if (
    languageCodeOrSpecification &&
    typeof languageCodeOrSpecification === 'object'
  ) {
    return languageCodeOrSpecification;
  }

  return getSpellcheckSpecification(languageCodeOrSpecification);
}

function normalizeDictionaryConfig(dictionarySource) {
  if (!dictionarySource || typeof dictionarySource !== 'object') {
    return null;
  }

  const { affUrl, dicUrl } = getPrimaryDictionaryUrls(dictionarySource);
  const dictionaryName =
    typeof dictionarySource.dictionaryName === 'string' &&
    dictionarySource.dictionaryName.trim()
      ? dictionarySource.dictionaryName.trim()
      : '';
  const languageCode =
    typeof dictionarySource.languageCode === 'string' &&
    dictionarySource.languageCode.trim()
      ? normalizeLanguageCode(dictionarySource.languageCode) ||
        dictionarySource.languageCode.trim().toLowerCase()
      : null;

  if (!affUrl || !dicUrl || !dictionaryName) {
    return null;
  }

  return {
    affUrl,
    dicUrl,
    dictionaryName,
    languageCode,
  };
}

function normalizeSuggestionDictionaryConfigs(
  dictionarySource,
  dictionaryConfig,
) {
  if (!dictionarySource || typeof dictionarySource !== 'object') {
    return [];
  }

  if (!dictionaryConfig) {
    return [];
  }

  const suggestionDictionaryUrls =
    getSuggestionDictionaryUrls(dictionarySource);
  if (
    !suggestionDictionaryUrls.affUrls.length &&
    !suggestionDictionaryUrls.dicUrl
  ) {
    return [];
  }

  const resolvedAffUrls = suggestionDictionaryUrls.affUrls.length
    ? suggestionDictionaryUrls.affUrls
    : [dictionaryConfig.affUrl];
  const resolvedDicUrl =
    suggestionDictionaryUrls.dicUrl || dictionaryConfig.dicUrl;

  return resolvedAffUrls.map((affUrl) => ({
    affUrl,
    dicUrl: resolvedDicUrl,
    dictionaryName: dictionaryConfig.dictionaryName,
    languageCode: dictionaryConfig.languageCode,
  }));
}

function getDictionaryConfig(languageCodeOrSpecification) {
  const dictionarySource = getDictionarySource(languageCodeOrSpecification);
  if (!dictionarySource) {
    return null;
  }

  return normalizeDictionaryConfig(dictionarySource);
}

function getSuggestionDictionaryConfigs(languageCodeOrSpecification) {
  const dictionarySource = getDictionarySource(languageCodeOrSpecification);
  if (!dictionarySource) {
    return [];
  }

  const dictionaryConfig = normalizeDictionaryConfig(dictionarySource);
  return normalizeSuggestionDictionaryConfigs(
    dictionarySource,
    dictionaryConfig,
  );
}

function mergeDictionarySuggestions(dictionaries, word, limit = 3) {
  const suggestionDictionaries = Array.isArray(dictionaries)
    ? dictionaries
    : [dictionaries];
  const maxSuggestions = Math.max(1, Number(limit) || 3);
  const mergedSuggestions = [];
  const seenSuggestions = new Set();

  suggestionDictionaries.forEach((dictionary) => {
    if (!dictionary?.loaded || typeof dictionary.suggest !== 'function') {
      return;
    }

    const suggestions = dictionary.suggest(word, maxSuggestions);
    if (!Array.isArray(suggestions)) {
      return;
    }

    suggestions.forEach((suggestion) => {
      if (
        typeof suggestion !== 'string' ||
        !suggestion ||
        seenSuggestions.has(suggestion)
      ) {
        return;
      }

      seenSuggestions.add(suggestion);
      mergedSuggestions.push(suggestion);
    });
  });

  return mergedSuggestions.slice(0, maxSuggestions);
}

/**
 * typo-js 1.3.2 keeps `dictionaryTable` as a `Map`; earlier releases — and
 * the plain-JSON side of a snapshot made before the upgrade — used a plain
 * word→flags object. Everything that reads a table goes through these two
 * helpers so both shapes behave identically, whichever a dictionary or a
 * restored snapshot happens to carry.
 */
function dictionaryTableHas(dictionaryTable, word) {
  if (dictionaryTable instanceof Map) {
    return dictionaryTable.has(word);
  }

  return Boolean(
    dictionaryTable &&
    typeof dictionaryTable === 'object' &&
    Object.prototype.hasOwnProperty.call(dictionaryTable, word),
  );
}

function* iterateDictionaryTableWords(dictionaryTable) {
  if (dictionaryTable instanceof Map) {
    yield* dictionaryTable.keys();
    return;
  }

  if (dictionaryTable && typeof dictionaryTable === 'object') {
    // for..in stays lazy — no Object.keys() array of every dictionary word
    // (tens of thousands for en_US) per keystroke.
    for (const word in dictionaryTable) {
      yield word;
    }
  }
}

function getDictionaryPrefixSuggestions(dictionaries, prefix, limit = 8) {
  const suggestionDictionaries = Array.isArray(dictionaries)
    ? dictionaries
    : [dictionaries];
  const normalizedPrefix = String(prefix || '').trim();
  const maxSuggestions = Math.max(1, Number(limit) || 8);

  if (!normalizedPrefix) {
    return [];
  }

  const normalizedPrefixLower = normalizedPrefix.toLocaleLowerCase();
  const mergedSuggestions = [];
  const seenSuggestions = new Set();

  suggestionDictionaries.forEach((dictionary) => {
    if (!dictionary?.loaded || !dictionary.dictionaryTable) {
      return;
    }

    for (const word of iterateDictionaryTableWords(
      dictionary.dictionaryTable,
    )) {
      if (typeof word !== 'string' || !word) {
        continue;
      }

      const lowerWord = word.toLocaleLowerCase();

      if (
        seenSuggestions.has(lowerWord) ||
        !lowerWord.startsWith(normalizedPrefixLower)
      ) {
        continue;
      }

      seenSuggestions.add(lowerWord);
      mergedSuggestions.push(word);

      if (mergedSuggestions.length >= maxSuggestions * 4) {
        break;
      }
    }
  });

  return mergedSuggestions
    .sort((left, right) => {
      if (left.length !== right.length) {
        return left.length - right.length;
      }

      return left.localeCompare(right, undefined, {
        sensitivity: 'base',
      });
    })
    .slice(0, maxSuggestions);
}

function hasWordBaseCharacter(word, languageCode) {
  const specification = getSpellcheckSpecification(languageCode);
  const normalizedWord = normalizeWord(word, languageCode);
  if (!normalizedWord) {
    return false;
  }

  if (typeof specification?.shouldCheckWord === 'function') {
    return Boolean(specification.shouldCheckWord(normalizedWord));
  }

  if (specification?.baseLetterPattern instanceof RegExp) {
    return testRegExp(specification.baseLetterPattern, normalizedWord);
  }

  return true;
}

/**
 * True when the word carries a base letter of ANY registered language whose
 * script the core would otherwise have had to know about.
 *
 * Replaces the old `hasKhmerBaseLetter`: the caller is never asking "is this
 * Khmer?", it is asking "is this a script whose word boundaries the plain-text
 * rules do not describe?" — the question the segmentation, ZWSP-separator and
 * re-segmentation paths all want answered. English (and any other plain,
 * space-separated language) declares no `baseLetterPattern`, so it never
 * matches here and those paths stay off, exactly as before.
 */
function hasAnyWordBaseCharacter(word) {
  return getAvailableSpellcheckSpecifications().some(
    (specification) =>
      specification.baseLetterPattern instanceof RegExp &&
      hasWordBaseCharacter(word, specification.languageCode),
  );
}

/**
 * The character this language puts between words — a zero-width space for
 * scripts that separate invisibly, a plain space otherwise (the default).
 */
function getWordSeparator(languageCode) {
  const specification = getSpellcheckSpecification(languageCode);
  const separator = specification?.wordSeparator;

  return typeof separator === 'string' && separator ? separator : ' ';
}

/** Every registered language that separates words with an invisible mark. */
function getInvisibleWordSeparators() {
  return Array.from(
    new Set(
      getAvailableSpellcheckSpecifications()
        .map((specification) => specification.wordSeparator)
        .filter(
          (separator) =>
            typeof separator === 'string' &&
            separator.length > 0 &&
            !/\S/u.test(separator) &&
            separator !== ' ',
        ),
    ),
  );
}

/**
 * `{ pattern, separator }` for every language that can repair typed whitespace
 * between its words — see `normalizeWordSeparators` in `shared.ts`.
 */
function getWordSeparatorRewrites() {
  return getAvailableSpellcheckSpecifications()
    .filter(
      (specification) =>
        specification.wordSeparatorPattern instanceof RegExp &&
        typeof specification.wordSeparator === 'string' &&
        specification.wordSeparator,
    )
    .map((specification) => ({
      pattern: specification.wordSeparatorPattern,
      separator: specification.wordSeparator,
    }));
}

/**
 * The menu label for a language's re-segmentation command, or `''` when it
 * offers none.
 *
 * This is the declarative opt-in that replaced the core's `=== 'km'` gates:
 * a language that can re-split a run of text into words names the command
 * here, and its provider backs it with `getSegmentationSuggestion` /
 * `postProcessTranscriptText`. No caller needs to know which language it is.
 */
function getSegmentationActionLabel(languageCode) {
  const label =
    getSpellcheckSpecification(languageCode)?.segmentationActionLabel;

  return typeof label === 'string' ? label.trim() : '';
}

/** Every registered language offering a re-segmentation command. */
function getSegmentationCapableSpecifications() {
  return getAvailableSpellcheckSpecifications().filter((specification) =>
    getSegmentationActionLabel(specification.languageCode),
  );
}

/** Autocomplete trigger characters contributed by registered languages. */
function getWordSuggestTriggerCharacters() {
  return Array.from(
    new Set(
      getAvailableSpellcheckSpecifications().flatMap((specification) =>
        Array.isArray(specification.suggestTriggerCharacters)
          ? specification.suggestTriggerCharacters
          : [],
      ),
    ),
  );
}

function detectLanguageCode(word) {
  for (const specification of getAvailableSpellcheckSpecifications()) {
    if (
      testRegExp(specification.exactWordPattern, word) &&
      hasWordBaseCharacter(word, specification.languageCode)
    ) {
      return specification.languageCode;
    }
  }

  return null;
}

function normalizeWord(word, languageCode) {
  const specification = getSpellcheckSpecification(languageCode);

  if (typeof specification?.normalizeWord === 'function') {
    return specification.normalizeWord(word);
  }

  return String(word || '');
}

function normalizeSpellcheckLookupWord(word, languageCode) {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);
  const normalizedWord = normalizeWord(
    word,
    normalizedLanguageCode || languageCode,
  );

  if (!normalizedWord) {
    return '';
  }

  return normalizedLanguageCode === 'en'
    ? normalizedWord.toLowerCase()
    : normalizedWord;
}

function getSpellcheckTokenPatterns() {
  return getAvailableSpellcheckSpecifications()
    .filter((specification) => specification.wordPattern instanceof RegExp)
    .map((specification) => ({
      languageCode: specification.languageCode,
      pattern: specification.wordPattern,
    }));
}

async function fetchDictionaryText(url) {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(
      `Failed to load dictionary file: ${url} (${response.status})`,
    );
  }

  return response.text();
}

async function loadDictionaryFromConfig(dictionaryConfig) {
  if (!dictionaryConfig) {
    return null;
  }

  if (typeof TypoConstructor !== 'function') {
    console.error('Typo.js failed to load; spellcheck is disabled.');
    return null;
  }

  const [affData, dicData] = await Promise.all([
    fetchDictionaryText(dictionaryConfig.affUrl),
    fetchDictionaryText(dictionaryConfig.dicUrl),
  ]);

  return new TypoConstructor(dictionaryConfig.dictionaryName, affData, dicData);
}

async function loadDictionary(languageCodeOrSpecification) {
  return loadDictionaryFromConfig(
    getDictionaryConfig(languageCodeOrSpecification),
  );
}

function createDictionarySnapshot(dictionary) {
  if (!dictionary?.loaded) {
    return null;
  }

  try {
    const snapshot = JSON.parse(JSON.stringify(dictionary));

    // typo-js 1.3.2's `dictionaryTable` is a `Map`, which JSON.stringify
    // flattens to `{}` — the round-trip above silently dropped every word and
    // the restored dictionary then threw `dictionaryTable.get is not a
    // function` from `check()`. Carry the table explicitly, as a JSON-safe
    // entries array (values are `null` or rule-code string arrays).
    if (dictionary.dictionaryTable instanceof Map) {
      snapshot.dictionaryTable = Array.from(
        dictionary.dictionaryTable.entries(),
      );
    }

    return snapshot;
  } catch (error) {
    console.error('Failed to serialize spellcheck dictionary.', error);
    return null;
  }
}

function restoreDictionaryFromSnapshot(dictionarySnapshot) {
  if (!dictionarySnapshot || typeof dictionarySnapshot !== 'object') {
    return null;
  }

  if (typeof TypoConstructor !== 'function') {
    console.error('Typo.js failed to load; spellcheck is disabled.');
    return null;
  }

  try {
    const dictionary = new TypoConstructor();
    if (typeof dictionary.load !== 'function') {
      return null;
    }

    dictionary.load(dictionarySnapshot);

    // `load()` copies the snapshot's fields verbatim, but the prototype's
    // `check()`/`suggest()` expect `dictionaryTable` to be a `Map` (typo-js
    // 1.3.2). Rebuild it from the snapshot's entries array — or from the
    // plain word→flags object a pre-upgrade snapshot carried.
    const { dictionaryTable } = dictionary;
    if (Array.isArray(dictionaryTable)) {
      dictionary.dictionaryTable = new Map(dictionaryTable);
    } else if (
      dictionaryTable &&
      typeof dictionaryTable === 'object' &&
      !(dictionaryTable instanceof Map)
    ) {
      dictionary.dictionaryTable = new Map(Object.entries(dictionaryTable));
    }

    return dictionary?.loaded ? dictionary : null;
  } catch (error) {
    console.error('Failed to restore spellcheck dictionary.', error);
    return null;
  }
}

export {
  createDictionarySnapshot,
  detectLanguageCode,
  dictionaryTableHas,
  getAvailableSpellcheckSpecifications,
  getDictionaryPrefixSuggestions,
  getDictionaryConfig,
  getSuggestionDictionaryConfigs,
  getSpellcheckSpecification,
  getSpellcheckTokenPatterns,
  getInvisibleWordSeparators,
  getSegmentationActionLabel,
  getSegmentationCapableSpecifications,
  getWordSeparator,
  getWordSeparatorRewrites,
  getWordSuggestTriggerCharacters,
  hasAnyWordBaseCharacter,
  hasWordBaseCharacter,
  loadDictionary,
  mergeDictionarySuggestions,
  normalizeSpellcheckLookupWord,
  normalizeLanguageCode,
  normalizeWord,
  restoreDictionaryFromSnapshot,
};
